    function escQ(s){return String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));}
    function renderQMCases(filter){
      const wrap=document.getElementById('qmCaseWrap');
      const list = filter==='all' ? QM_CASES : QM_CASES.filter(t=>t.key===filter);
      wrap.innerHTML = list.map(t=>{
        const sol = t.sol.map(s=>'<li>'+escQ(s)+'</li>').join('');
        const cards = t.cases.map(c=>{
          const tags=(c.defects||[]).map(d=>'<span class="qm-tag">'+escQ(d)+'</span>').join('');
          const src=c.url?'<a class="qm-src" href="'+escQ(c.url)+'" target="_blank" rel="noopener">通报原文 ↗</a>':'';
          return '<article class="qm-case"><div class="qm-case-h">'+escQ(c.company)+
            '<span class="qm-case-loc">'+escQ(c.prov)+' '+escQ(c.year)+' · '+escQ(c.level)+'</span></div>'+
            '<div class="qm-tags">'+tags+'</div>'+
            '<div class="qm-meas"><b>官方处理措施：</b>'+escQ(c.measure)+'</div>'+
            '<div class="qm-sum">'+escQ(c.summary)+'</div>'+src+'</article>';
        }).join('');
        return '<div class="qm-theme"><div class="qm-theme-h">'+escQ(t.name)+
          '<span class="qm-cat">对应：'+escQ(t.cat)+'</span></div>'+
          '<div class="qm-sol"><h4>🛠 解决措施 / 整改要点</h4><ul>'+sol+'</ul></div>'+
          '<div class="qm-cards">'+cards+'</div></div>';
      }).join('');
    }
    document.getElementById('qmCaseChips').addEventListener('click',e=>{
      const b=e.target.closest('.qm-chip'); if(!b)return;
      document.querySelectorAll('#qmCaseChips .qm-chip').forEach(x=>x.classList.remove('active'));
      b.classList.add('active'); renderQMCases(b.dataset.qmk);
    });
    renderQMCases('all');
  

