const Q=document.getElementById('q'),CH=document.getElementById('chips'),MAIN=document.getElementById('main'),EMPTY=document.getElementById('empty');
let curCat='all';
function norm(s){return (s||'').toLowerCase();}
function apply(){
  const kw=norm(Q.value.trim());
  let shown=0;
  document.querySelectorAll('.cat').forEach(sec=>{
    let s=0;
    sec.querySelectorAll('.doc').forEach(d=>{
      const hay=norm(d.innerText);
      const okC = curCat==='all' || sec.id==='cat-'+curCat;
      const okK = !kw || hay.includes(kw);
      const vis = okC && okK;
      d.style.display = vis?'':'none';
      if(vis) s++;
    });
    sec.style.display = (curCat==='all'||sec.id==='cat-'+curCat) && s>0 ? '' : 'none';
    shown+=s;
  });
  EMPTY.style.display = shown?'none':'block';
}
Q.addEventListener('input',apply);
CH.addEventListener('click',e=>{
  const b=e.target.closest('.chip'); if(!b)return;
  curCat=b.dataset.cat;
  CH.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));
  b.classList.add('active'); apply();
});
